  "headline": "Phenytoin sodium is not on FDA's shortage list as of 2026-10-21; our supply traces to a relabel/repack plant with a VAI inspection on 2026-08-12 and a Warning Letter on 2017-06-05",
  "headline_cites": ["D4", "E10", "E8", "E9"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows phenytoin sodium is not listed as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Our product label identifies A-S Medication Solutions as the labeler and plant, which performs relabel and repack operations and is a registered plant.",
      "cites": ["E10"]
    },
    {
      "text": "FDA inspected that plant on 2026-08-12 and classified the inspection VAI.",
      "cites": ["E8"]
    },
    {
      "text": "The same plant received a Warning Letter on 2017-06-05.",
      "cites": ["E9"]
    },
    {
      "text": "Earlier FDA inspections of the plant in 2009, 2012, 2013, and 2018 were also classified VAI.",
      "cites": ["E4", "E5", "E6", "E7"]
    },
    {
      "text": "Current inventory across our sites ranges from 13.2 to 30.6 days on hand for the 100 mg capsule presentation.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The top-ranked purchasing option is to buy from Amneal Pharmaceuticals LLC, which is not on FDA's shortage list today, though its label names no plant we could place.",
      "cites": ["D5"]
    }
  ]
}
